package com.schoolmanagement.qr;
import com.google.zxing.*; import com.google.zxing.client.j2se.MatrixToImageWriter; import com.google.zxing.common.BitMatrix; import com.schoolmanagement.student.*; import com.schoolmanagement.school.*; import com.schoolmanagement.security.UserContext; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.io.*; import java.security.*; import java.util.*; import java.util.Base64;
@Service public class QrService { private final QrCredentialRepository repo;private final StudentRepository students;private final SchoolRepository schools;private final UserContext ctx; public QrService(QrCredentialRepository r,StudentRepository s,SchoolRepository sc,UserContext c){repo=r;students=s;schools=sc;ctx=c;}
 private String hash(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 @Transactional public Map<String,Object> issue(Long studentId){Student s=students.findByIdAndSchoolId(studentId,ctx.schoolId()).orElseThrow(()->new NoSuchElementException("Student not found"));String token=UUID.randomUUID()+"-"+UUID.randomUUID();QrCredential q=new QrCredential();q.setSchool(schools.findById(ctx.schoolId()).orElseThrow());q.setStudent(s);q.setTokenHash(hash(token));repo.save(q);try{BitMatrix matrix=new com.google.zxing.qrcode.QRCodeWriter().encode(token,BarcodeFormat.QR_CODE,320,320);ByteArrayOutputStream out=new ByteArrayOutputStream();MatrixToImageWriter.writeToStream(matrix,"PNG",out);return Map.of("credentialId",q.getId(),"studentId",studentId,"qrToken",token,"qrImageBase64",Base64.getEncoder().encodeToString(out.toByteArray()),"warning","Treat this token as a secret. It is shown only when issued.");}catch(Exception e){throw new IllegalStateException("Could not generate QR image",e);}}
 public QrCredential validate(String token){return repo.findByTokenHashAndActiveTrue(hash(token)).orElseThrow(()->new IllegalArgumentException("Invalid or revoked QR credential"));}
 @Transactional public void revoke(Long credentialId){QrCredential q=repo.findById(credentialId).orElseThrow(()->new NoSuchElementException("Credential not found"));if(!q.getSchool().getId().equals(ctx.schoolId()))throw new NoSuchElementException("Credential not found");q.setActive(false);q.setRevokedAt(java.time.Instant.now());repo.save(q);}
}
